// resolve_article_field resolves the columns of `Article`.
fn resolve_article_field(_ graphql.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(article_value((it as ArticleNode).article, info.field_name)))
}

fn article_value(row articles_models.Article, field string) graphql.Value {
	return match field {
		'id' { graphql.Value(row.id.str()) }
		'slug' { graphql.Value(string(row.slug)) }
		'userID' { graphql.Value(row.user_id.str()) }
		'title' { graphql.Value(string(row.title)) }
		'summary' { graphql.Value(string(row.summary)) }
		'body' { graphql.Value(string(row.body)) }
		'publishedAt' {
			if v := row.published_at { graphql.Value(v.format_rfc3339()) } else { graphql.null }
		}
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		'updatedAt' { graphql.Value(row.updated_at.format_rfc3339()) }
		'deletedAt' {
			if v := row.deleted_at { graphql.Value(v.format_rfc3339()) } else { graphql.null }
		}
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `Article` list.
fn (q ArticleQuery) graphql_where(args map[string]graphql.Value) !ArticleQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...article_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `Article` list: `where`, `orderBy`,
// `limit` and `offset`.
fn (q ArticleQuery) graphql_args(args map[string]graphql.Value) !ArticleQuery {
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := article_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := args['limit'] {
		if limit is int {
			next = next.limit(limit)
		}
	}
	if offset := args['offset'] {
		if offset is int {
			next = next.offset(offset)
		}
	}
	return next
}

// article_order returns the orders of an `orderBy` of `Article`, and with `with_key`,
// the key last, unless it orders by it already.
fn article_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'int' }
				keyed = true
			}
			'SLUG' {
				orders << load.Order{ column: 'slug', desc: desc, typ: 'string' }
			}
			'USER_ID' {
				orders << load.Order{ column: 'user_id', desc: desc, typ: 'int' }
			}
			'TITLE' {
				orders << load.Order{ column: 'title', desc: desc, typ: 'string' }
			}
			'SUMMARY' {
				orders << load.Order{ column: 'summary', desc: desc, typ: 'string' }
			}
			'BODY' {
				orders << load.Order{ column: 'body', desc: desc, typ: 'string' }
			}
			'PUBLISHED_AT' {
				orders << load.Order{ column: 'published_at', desc: desc, typ: '?time.Time' }
			}
			'CREATED_AT' {
				orders << load.Order{ column: 'created_at', desc: desc, typ: 'time.Time' }
			}
			'UPDATED_AT' {
				orders << load.Order{ column: 'updated_at', desc: desc, typ: 'time.Time' }
			}
			'DELETED_AT' {
				orders << load.Order{ column: 'deleted_at', desc: desc, typ: '?time.Time' }
			}
			'COMMENTS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "comments" AS "t1" WHERE "t1"."owner_id" = "t0"."id" AND "t1"."owner_type" = \'Article\' AND "t1"."deleted_at" IS NULL)', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a ArticleOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'int'
		}
	}
	return orders
}

