// resolve_user_field resolves the columns of `User`.
fn resolve_user_field(_ graphql.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(user_value((it as UserNode).user, info.field_name)))
}

fn user_value(row users_models.User, field string) graphql.Value {
	return match field {
		'id' { graphql.Value(row.id.str()) }
		'slug' { graphql.Value(string(row.slug)) }
		'name' { graphql.Value(string(row.name)) }
		'email' { graphql.Value(string(row.email)) }
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		'updatedAt' { graphql.Value(row.updated_at.format_rfc3339()) }
		'deletedAt' {
			if v := row.deleted_at { graphql.Value(v.format_rfc3339()) } else { graphql.null }
		}
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `User` list.
fn (q UserQuery) graphql_where(args map[string]graphql.Value) !UserQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...user_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `User` list: `where`, `orderBy`,
// `limit` and `offset`.
fn (q UserQuery) graphql_args(args map[string]graphql.Value) !UserQuery {
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := user_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := args['limit'] {
		if limit is int {
			next = next.limit(limit)
		}
	}
	if offset := args['offset'] {
		if offset is int {
			next = next.offset(offset)
		}
	}
	return next
}

// user_order returns the orders of an `orderBy` of `User`, and with `with_key`,
// the key last, unless it orders by it already.
fn user_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'int' }
				keyed = true
			}
			'SLUG' {
				orders << load.Order{ column: 'slug', desc: desc, typ: 'string' }
			}
			'NAME' {
				orders << load.Order{ column: 'name', desc: desc, typ: 'string' }
			}
			'EMAIL' {
				orders << load.Order{ column: 'email', desc: desc, typ: 'string' }
			}
			'CREATED_AT' {
				orders << load.Order{ column: 'created_at', desc: desc, typ: 'time.Time' }
			}
			'UPDATED_AT' {
				orders << load.Order{ column: 'updated_at', desc: desc, typ: 'time.Time' }
			}
			'DELETED_AT' {
				orders << load.Order{ column: 'deleted_at', desc: desc, typ: '?time.Time' }
			}
			'ARTICLES_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "articles" AS "t1" WHERE "t1"."user_id" = "t0"."id" AND "t1"."deleted_at" IS NULL)', desc: desc, typ: 'int' }
			}
			'POSTS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "posts" AS "t1" WHERE "t1"."user_id" = "t0"."id" AND "t1"."deleted_at" IS NULL)', desc: desc, typ: 'int' }
			}
			'COMMENTS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "comments" AS "t1" WHERE "t1"."user_id" = "t0"."id" AND "t1"."deleted_at" IS NULL)', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a UserOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'int'
		}
	}
	return orders
}

// user_where returns the conditions of a `UserWhereInput`.
fn user_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
